#!/usr/bin/env bash
# Read-only: properties of the line table and transaction summary components on the org's RLM_Quote_Record_Page
sf data query --use-tooling-api --query "SELECT Metadata FROM FlexiPage WHERE DeveloperName = 'RLM_Quote_Record_Page'" --target-org target --json 2>/dev/null | jq -c '[.result.records[0].Metadata.flexiPageRegions[]?.itemInstances[]?.componentInstance | select(.componentName != null and (.componentName|test("salesTxnLineTable|transactionSummary"))) | {c: .componentName, props: [.componentInstanceProperties[]? | [.name, (.value // ([.valueList.valueListItems[]?.value] | join(", ")))]]}]'
